32	func newServer(db service.DatabaseReader, adp service.AdapterCaller) *httptest.Server {
33		gin.SetMode(gin.TestMode)
34		svc := service.New(db, adp, 30*time.Minute)
35		h := handler.New(svc)
36		r := gin.New()
37		r.Use(gin.Recovery())
38		r.GET("/healthz", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"status": "ok"}) })
39		api := r.Group("/api")
40		h.RegisterRoutes(api)
41		return httptest.NewServer(r)
42	}
43	
44	func get(t *testing.T, srv *httptest.Server, path string) *http.Response {
45		t.Helper()
46		req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, srv.URL+path, nil)
47		if err != nil {
48			t.Fatalf("new request GET %s: %v", path, err)
49		}
50		resp, err := http.DefaultClient.Do(req)
51		if err != nil {
52			t.Fatalf("GET %s: %v", path, err)
53		}
54		return resp
55	}
56	
57	func post(t *testing.T, srv *httptest.Server, path, body string) *http.Response {
58		t.Helper()
59		req, err := http.NewRequestWithContext(context.Background(), http.MethodPost, srv.URL+path, strings.NewReader(body))
60		if err != nil {
61			t.Fatalf("new request POST %s: %v", path, err)
62		}
63		req.Header.Set("Content-Type", "application/json")
64		resp, err := http.DefaultClient.Do(req)
65		if err != nil {
66			t.Fatalf("POST %s: %v", path, err)
67		}
68		return resp
69	}
70	
71	type testAPIEnvelope struct {
72		Success bool            `json:"success"`
73		Data    json.RawMessage `json:"data"`
74		Error   *testAPIError   `json:"error"`
75	}
76	
77	type testAPIError struct {
78		Code      domain.ErrorCode `json:"code"`
79		Message   string           `json:"message"`
80		Retryable bool             `json:"retryable"`
81		Source    string           `json:"source"`
82	}
83	
84	func decodeAPIData[T any](t *testing.T, resp *http.Response) T {
85		t.Helper()
86		var envelope testAPIEnvelope
87		if err := json.NewDecoder(resp.Body).Decode(&envelope); err != nil {
88			t.Fatalf("decode response envelope: %v", err)
89		}
90		if !envelope.Success {
91			t.Fatalf("expected success envelope")
92		}
93		if envelope.Error != nil {
94			t.Fatalf("did not expect error field in success envelope: %+v", envelope.Error)
95		}
96		var out T
97		if err := json.Unmarshal(envelope.Data, &out); err != nil {
98			t.Fatalf("decode response data: %v", err)
99		}
100		return out
101	}
102	
103	func decodeAPIError(t *testing.T, resp *http.Response) testAPIError {
104		t.Helper()
105		var envelope testAPIEnvelope
106		if err := json.NewDecoder(resp.Body).Decode(&envelope); err != nil {
107			t.Fatalf("decode error envelope: %v", err)
108		}
109		if envelope.Success {
110			t.Fatalf("expected error envelope")
111		}
112		if envelope.Error == nil {
113			t.Fatalf("expected error body")
114		}
115		return *envelope.Error
116	}
