118	// --- T5 scenario 1: first import — persisted by adapter and returned as normalized detail ---
119	
120	func TestImport_FirstImport_200WithWorkspaceDetail(t *testing.T) {
121		ws := testhelpers.NewWorkspace(wsID, "My Workspace", "my-workspace")
122		feature := testhelpers.NewFeature(wsID, featureID, "Workspace Data Backend", "in_progress", "implementation")
123		task := testhelpers.NewTask(wsID, featureID, taskID, "Implement API", "ready", nil)
124		src := testhelpers.NewGitHubSource(wsID, repoURL)
125		successRun := testhelpers.NewSyncRun(wsID, "api_import", "full", "success")
126		if err := successRun.FinishedAt.Scan(time.Now().UTC()); err != nil {
127			t.Fatal(err)
128		}
129		db := &testhelpers.FakeDB{
130			Workspaces: []database.Workspace{ws},
131			SyncRuns:   []database.WorkspaceSyncRun{successRun},
132			Features:   []database.WorkspaceFeature{feature},
133			Tasks:      []database.WorkspaceTask{task},
134			GitHubSrcs: map[string]database.WorkspaceGitHubSource{wsID: src},
135		}
136		adp := &testhelpers.FakeAdapter{ImportedWorkspaceID: wsID}
137		srv := newServer(db, adp)
138		defer srv.Close()
139	
140		resp := post(t, srv, "/api/workspaces/import",
141			`{"repo_url":"https://github.com/testorg/test-repo","name":"My Workspace"}`)
142		defer func() { _ = resp.Body.Close() }()
143	
144		if resp.StatusCode != http.StatusOK {
145			t.Fatalf("expected 200, got %d", resp.StatusCode)
146		}
147		detail := decodeAPIData[domain.WorkspaceDetail](t, resp)
148		if detail.ID != wsID {
149			t.Errorf("expected workspace ID %s, got %s", wsID, detail.ID)
150		}
151		if detail.RepoURL != repoURL {
152			t.Errorf("expected repo_url %s, got %s", repoURL, detail.RepoURL)
153		}
154		if detail.SourceState.Stale {
155			t.Error("expected fresh source_state after completed import")
156		}
157		if len(detail.Features) != 1 {
158			t.Errorf("expected imported feature summary, got %d features", len(detail.Features))
159		}
160		if len(detail.Tasks) != 1 {
161			t.Errorf("expected imported task summary, got %d tasks", len(detail.Tasks))
162		}
163	}
