300			a, b := out[i], out[j]
301			switch filters.Sort {
302			case "title_asc":
303				return a.Title < b.Title
304			case "title_desc":
305				return a.Title > b.Title
306			case "status_asc":
307				return derefString(a.FeatureStatus) < derefString(b.FeatureStatus)
