// Package authmw provides authentication middleware and context helpers.
package authmw

import "context"

// contextKey is the unexported type for context keys in this package.
type contextKey int

const authCtxKey contextKey = 0

// AuthCtx holds the authenticated caller's identity and access scope.
type AuthCtx struct {
	UserID                 string
	OrganizationID         string
	AccessibleWorkspaceIDs []string
}

// FromContext extracts the AuthCtx stored by RequireAuth.
// Returns (nil, false) if no auth context is present.
func FromContext(ctx context.Context) (*AuthCtx, bool) {
	v, ok := ctx.Value(authCtxKey).(*AuthCtx)
	return v, ok && v != nil
}

// SetAuthCtx returns a derived context with the given AuthCtx attached.
// Used by RequireAuth and by tests that need to inject an auth context.
func SetAuthCtx(ctx context.Context, ac *AuthCtx) context.Context {
	return context.WithValue(ctx, authCtxKey, ac)
}
package authmw

import (
	"errors"
	"net/http"

	"github.com/gin-gonic/gin"

	usersvc "github.com/tiendv89/workflow-backend/internal/serviceclient/user_service"
)

const sessionCookieName = "session"

// RequireAuth returns a gin middleware that validates the session cookie via user-service.
// On success it attaches AuthCtx to the request context.
// On missing/invalid cookie: 401.
// On service failure: 503.
func RequireAuth(client *usersvc.Client) gin.HandlerFunc {
	return func(c *gin.Context) {
		cookieVal, err := c.Cookie(sessionCookieName)
		if err != nil || cookieVal == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized"})
			return
		}

		info, err := client.ValidateSession(c.Request.Context(), cookieVal)
		if err != nil {
			if errors.Is(err, usersvc.ErrUnauthenticated) {
				c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized"})
				return
			}
			c.AbortWithStatusJSON(http.StatusServiceUnavailable, gin.H{"error": "authentication service unavailable"})
			return
		}

		ac := &AuthCtx{
			UserID:                 info.UserID,
			OrganizationID:         info.OrganizationID,
			AccessibleWorkspaceIDs: info.AccessibleWorkspaceIDs,
		}
		c.Request = c.Request.WithContext(SetAuthCtx(c.Request.Context(), ac))
		c.Set("auth_ctx", ac)
		c.Next()
	}
}
