func (f *FakeDB) ListWorkspaces(ctx context.Context) ([]database2.Workspace, error) {
	if f.ListWorkspacesErr != nil {
		return nil, f.ListWorkspacesErr
	}
	ac, hasAuth := authmw.FromContext(ctx)
	if !hasAuth {
		return f.Workspaces, nil
	}
	if len(ac.AccessibleWorkspaceIDs) == 0 {
		return []database2.Workspace{}, nil
	}
	allowed := make(map[string]struct{}, len(ac.AccessibleWorkspaceIDs))
	for _, id := range ac.AccessibleWorkspaceIDs {
		allowed[id] = struct{}{}
	}
	out := make([]database2.Workspace, 0, len(f.Workspaces))
	for _, w := range f.Workspaces {
		if _, ok := allowed[database2.UUIDString(w.ID)]; ok {
			out = append(out, w)
